import{_ as a,a0 as n,w as u,s as p,ao as l,I as s,x as r,a1 as o,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse(`{"title":"Linux常見問題解答--如何修復 tar：由於前一個錯誤導致於失敗狀態中退出  | LCTT x X-CMD","titleTemplate":false,"description":"Linux常見問題解答--如何修復 tar：由於前一個錯誤導致於失敗狀態中退出  | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux常見問題解答--如何修復 tar：由於前一個錯誤導致於失敗狀態中退出  | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux常見問題解答--如何修復 tar：由於前一個錯誤導致於失敗狀態中退出  | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150709 Linux FAQs with Answers--How to fix 'tar--Exiting with failure status due to previous errors'","title":"Linux常見問題解答--如何修復 tar：由於前一個錯誤導致於失敗狀態中退出 ","tag":"201507","desc":""},"relativePath":"201507/20150709 Linux FAQs with Answers--How to fix 'tar--Exiting with failure status due to previous errors'.md","filePath":"[post].md"}`),d={name:"201507/20150709 Linux FAQs with Answers--How to fix 'tar--Exiting with failure status due to previous errors'.md"};function x(f,t,m,_,g,w){const e=n("Link");return u(),p("div",null,[t[13]||(t[13]=l(`<h1 id="linux常見問題解答-如何修復-tar-由於前一個錯誤導致於失敗狀態中退出" tabindex="-1">Linux常見問題解答--如何修復&quot;tar：由於前一個錯誤導致於失敗狀態中退出&quot; <a class="header-anchor" href="#linux常見問題解答-如何修復-tar-由於前一個錯誤導致於失敗狀態中退出" aria-label="Permalink to “Linux常見問題解答--如何修復tar：由於前一個錯誤導致於失敗狀態中退出”">​</a></h1><blockquote><p><strong>問題</strong>: 當我想試着用tar命令來創建一個壓縮文件時，總在執行過程中失敗，並且拋出一個錯誤説明&quot;tar：由於前一個錯誤導致於失敗狀態中退出&quot;(&quot;Exiting with failure status due to previous errors&quot;). 什麼導致這個錯誤的發生，要如何解決？</p></blockquote><p><img src="https://farm9.staticflickr.com/8863/17631029953_1140fe2dd3_b.jpg" alt=""></p><p>如果當你執行tar命令時，遇到了下面的錯誤，那麼最有可能的原因是對於你想用tar命令壓縮的某個文件中，你並不具備其讀權限。</p><pre><code>tar: Exiting with failure status due to previous errors
</code></pre><p>那麼我們要如何確定引起錯誤的這個（些）文件呢？或者如何確定其它的錯誤根源？</p><p>事實上tar命令應該會打印出所謂的“上一個錯誤”(&quot;previous errors&quot;)到底是什麼錯誤，但是如果你讓tar運行在詳細模式（即verbose mode，例如, -cvf)，那麼你會很容易錯失這些信息。要找到這些信息，你可以像下面那樣，把tar的標準輸出（stdout)信息過濾掉。</p><pre><code>$ tar cvzfz backup.tgz my_program/ &gt; /dev/null
</code></pre><p>然後你會看到tar輸出的標準錯誤(stderr)信息。（LCTT 譯註：自然，不用 v 參數也可以。）</p><pre><code>tar: my_program/src/lib/.conf.db.~lock~: Cannot open: Permission denied
tar: Exiting with failure status due to previous errors
</code></pre><p>你可以從上面的例子中看到，引起錯誤的原因的確是“讀權限不允許”（denied read permission.)要解決這個問題，只要簡單地更改(或移除)問題文件的權限，然後重新執行tar命令即可。</p><hr>`,12)),s("p",null,[t[1]||(t[1]=r("via: ",-1)),o(e,{href:"http://ask.xmodulo.com/tar-exiting-with-failure-status-due-to-previous-errors.html"},{default:i(()=>[...t[0]||(t[0]=[r("http://ask.xmodulo.com/tar-exiting-with-failure-status-due-to-previous-errors.html",-1)])]),_:1})]),s("p",null,[t[5]||(t[5]=r("作者：",-1)),o(e,{href:"http://ask.xmodulo.com/author/nanni"},{default:i(()=>[...t[2]||(t[2]=[r("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=r(" 譯者：",-1)),o(e,{href:"https://github.com/XLCYun"},{default:i(()=>[...t[3]||(t[3]=[r("XLCYun(袖裏藏雲)",-1)])]),_:1}),t[7]||(t[7]=r(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[4]||(t[4]=[r("wxy",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=r("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[8]||(t[8]=[r("LCTT",-1)])]),_:1}),t[11]||(t[11]=r(" 原創翻譯，",-1)),o(e,{href:"https://linux.cn/"},{default:i(()=>[...t[9]||(t[9]=[r("Linux中國",-1)])]),_:1}),t[12]||(t[12]=r(" 榮譽推出",-1))])])}const v=a(d,[["render",x]]);export{C as __pageData,v as default};
